在three.js中加载glb模型，需要使用three.js提供的GLTFLoader来加载和解析模型文件。以下是一个基本的加载glb模型的示例代码：

```js
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";

// 创建场景、相机和渲染器
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
const renderer = new THREE.WebGLRenderer();
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

// 创建光源
const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
directionalLight.position.set(-10, 10, 5);
scene.add(ambientLight, directionalLight);

// 加载模型
const loader = new GLTFLoader();
const modelUrl = "model.glb";
loader.load(
  modelUrl,
  function (gltf) {
    // 添加模型到场景中
    scene.add(gltf.scene);
    // 调整模型位置和大小
    gltf.scene.position.set(0, 0, 0);
    gltf.scene.scale.set(1, 1, 1);
    // 打印模型的材质信息
    console.log(gltf.scene.children[0].material);
  },
  undefined,
  function (error) {
    console.error(error);
  }
);

// 渲染场景
function animate() {
  requestAnimationFrame(animate);
  renderer.render(scene, camera);
}
animate();
```

在上面的代码中，GLTFLoader使用内置的WebGL渲染器来加载glb文件，并将模型添加到场景中。在回调函数中，使用gltf.scene属性访问模型，可以调整模型的位置和大小。可以使用console.log函数打印材质信息来确保模型中的材质被正确加载。

需要注意的是，在加载和解析glb文件后，需要将材质映射到几何体上，否则就会导致纹理无法正常显示。可以通过修改材质对象的map属性来实现纹理映射：

```js
loader.load(
  modelUrl,
  function (gltf) {
    const mesh = gltf.scene.children[0];
    // 将纹理映射到材质上
    const texture = gltf.scene.children[0].material.map;
    texture.encoding = THREE.sRGBEncoding;
    mesh.material = new THREE.MeshStandardMaterial({
      map: texture,
      roughness: 0.5,
      metalness: 0.5,
    });
    // 添加模型到场景中
    scene.add(mesh);
  },
  undefined,
  function (error) {
    console.error(error);
  }
);
```

在上面的代码中，使用了材质的map属性来指定纹理，并将其设置为一个新的网格标准材质，以便将纹理应用到几何体上。至此，glb模型应该就能正常显示材质和贴图了。

